// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title BlueCarbonRegistry
 * @dev Smart Contract for Decentralized Blue Carbon Project Lifecycle & Cryptographic Verification
 * @notice Designed for BlueChain Registry - Smart India Hackathon Prototype
 */

interface IBlueCarbonToken {
    function mint(address to, uint256 amount, string memory projectHash) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

contract BlueCarbonRegistry {
    address public governmentAdmin;
    IBlueCarbonToken public carbonToken;

    enum EcosystemType { Mangrove, Seagrass, SaltMarsh }
    enum ProjectStatus { Pending, Verified, Rejected }

    struct Project {
        string id;
        string name;
        EcosystemType ecosystem;
        string description;
        string locationState;
        string locationDistrict;
        string gpsCoordinates;
        uint256 areaHectares; // Scaled by 100 (e.g. 15000 = 150.00 ha)
        uint256 estimatedCarbonTons; // Metric Tons CO2e
        uint256 carbonCreditsIssued;
        uint256 carbonCreditsAvailable;
        address ownerWallet;
        ProjectStatus status;
        string ipfsMetadataHash;
        string verificationRemarks;
        uint256 timestamp;
        bytes32 txHash;
    }

    struct CarbonTransaction {
        bytes32 txHash;
        string projectId;
        address sender;
        address recipient;
        uint256 creditsAmount;
        uint256 pricePerCreditETH;
        uint256 timestamp;
        string txType; // "MINT", "PURCHASE", "RETIRE"
    }

    mapping(string => Project) public projects;
    string[] public projectIds;
    CarbonTransaction[] public auditTrail;

    event ProjectRegistered(string indexed id, string name, address indexed owner, uint256 estimatedCarbon);
    event ProjectVerified(string indexed id, address indexed verifier, uint256 creditsMinted, string remarks);
    event ProjectRejected(string indexed id, address indexed verifier, string reason);
    event CreditsPurchased(string indexed projectId, address indexed buyer, uint256 amount, uint256 totalPrice);

    modifier onlyAdmin() {
        require(msg.sender == governmentAdmin, "Caller is not government admin");
        _;
    }

    constructor() {
        governmentAdmin = msg.sender;
    }

    function setCarbonToken(address _tokenAddress) external onlyAdmin {
        carbonToken = IBlueCarbonToken(_tokenAddress);
    }

    /**
     * @dev Register a new Blue Carbon Project on-chain
     */
    function registerProject(
        string memory _id,
        string memory _name,
        EcosystemType _ecosystem,
        string memory _description,
        string memory _state,
        string memory _district,
        string memory _gps,
        uint256 _areaHectares,
        uint256 _estimatedCarbon,
        string memory _ipfsHash
    ) external returns (bytes32) {
        require(bytes(projects[_id].id).length == 0, "Project ID already exists");

        bytes32 txHash = keccak256(abi.encodePacked(_id, msg.sender, block.timestamp, block.number));

        projects[_id] = Project({
            id: _id,
            name: _name,
            ecosystem: _ecosystem,
            description: _description,
            locationState: _state,
            locationDistrict: _district,
            gpsCoordinates: _gps,
            areaHectares: _areaHectares,
            estimatedCarbonTons: _estimatedCarbon,
            carbonCreditsIssued: 0,
            carbonCreditsAvailable: 0,
            ownerWallet: msg.sender,
            status: ProjectStatus.Pending,
            ipfsMetadataHash: _ipfsHash,
            verificationRemarks: "",
            timestamp: block.timestamp,
            txHash: txHash
        });

        projectIds.push(_id);

        emit ProjectRegistered(_id, _name, msg.sender, _estimatedCarbon);
        return txHash;
    }

    /**
     * @dev Government Officer approves project & triggers credit minting
     */
    function verifyAndIssueCredits(
        string memory _id,
        uint256 _creditsToMint,
        string memory _remarks
    ) external onlyAdmin returns (bool) {
        Project storage proj = projects[_id];
        require(bytes(proj.id).length > 0, "Project not found");
        require(proj.status == ProjectStatus.Pending, "Project is not in pending state");

        proj.status = ProjectStatus.Verified;
        proj.carbonCreditsIssued = _creditsToMint;
        proj.carbonCreditsAvailable = _creditsToMint;
        proj.verificationRemarks = _remarks;

        bytes32 mintTx = keccak256(abi.encodePacked("MINT", _id, block.timestamp));

        auditTrail.push(CarbonTransaction({
            txHash: mintTx,
            projectId: _id,
            sender: address(0),
            recipient: proj.ownerWallet,
            creditsAmount: _creditsToMint,
            pricePerCreditETH: 0,
            timestamp: block.timestamp,
            txType: "MINT"
        }));

        if (address(carbonToken) != address(0)) {
            carbonToken.mint(proj.ownerWallet, _creditsToMint, proj.ipfsMetadataHash);
        }

        emit ProjectVerified(_id, msg.sender, _creditsToMint, _remarks);
        return true;
    }

    /**
     * @dev Government Officer rejects fraudulent or non-compliant project
     */
    function rejectProject(string memory _id, string memory _reason) external onlyAdmin {
        Project storage proj = projects[_id];
        require(bytes(proj.id).length > 0, "Project not found");
        proj.status = ProjectStatus.Rejected;
        proj.verificationRemarks = _reason;

        emit ProjectRejected(_id, msg.sender, _reason);
    }

    /**
     * @dev Purchase carbon credits from verified project
     */
    function buyCarbonCredits(string memory _id, uint256 _creditAmount) external payable returns (bytes32) {
        Project storage proj = projects[_id];
        require(proj.status == ProjectStatus.Verified, "Project not verified");
        require(proj.carbonCreditsAvailable >= _creditAmount, "Insufficient carbon credits available");

        proj.carbonCreditsAvailable -= _creditAmount;

        bytes32 purchaseTxHash = keccak256(abi.encodePacked("PURCHASE", _id, msg.sender, block.timestamp));

        auditTrail.push(CarbonTransaction({
            txHash: purchaseTxHash,
            projectId: _id,
            sender: proj.ownerWallet,
            recipient: msg.sender,
            creditsAmount: _creditAmount,
            pricePerCreditETH: msg.value / _creditAmount,
            timestamp: block.timestamp,
            txType: "PURCHASE"
        }));

        payable(proj.ownerWallet).transfer(msg.value);

        emit CreditsPurchased(_id, msg.sender, _creditAmount, msg.value);
        return purchaseTxHash;
    }

    function getAuditTrailCount() external view returns (uint256) {
        return auditTrail.length;
    }
}

